    const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0'),key=`${y}-${m}-${day}`,r=byMonth.get(`${y}-${m}`),s=r?dashboardSellerForRecord(r):null,data=s?.daily?.[key]||{status:'pending'};
