function dashLabelForKey(k){if(dashboardRangeStart&&dashboardRangeEnd)return `${String(k).slice(8,10)}/${String(k).slice(5,7)}`;return String(+String(k).slice(-2))}
function isDashboardLaunchedDay(d){if(!d)return false;const st=String(d.status||'');if(['off','medical','justified'].includes(st))return false;if(['done','partial'].includes(st))return true;return ['general','eligible','invoiceCount','nfs','warranty','other','mixed','warrantyQty','commissionMercantile','commissionService'].some(f=>num(d[f])>0)}
function dashRows(period='month'){const all=Object.entries(seller?.daily||{}).filter(([,d])=>isDashboardLaunchedDay(d)).sort(([a],[b])=>a.localeCompare(b)).slice(0,31);if(period==='month')return all;const[y,m]=String(record?.month||month).split('-').map(Number),last=new Date(y,m,0).getDate(),anchor=(y===now.getFullYear()&&m===now.getMonth()+1)?now.getDate():last;if(period==='week'){const d=new Date(y,m-1,anchor),dow=(d.getDay()+6)%7,start=Math.max(1,anchor-dow),end=Math.min(last,start+6);return all.filter(([k])=>{const x=+k.slice(-2);return x>=start&&x<=end})}if(period==='fortnight'){const start=anchor<=15?1:16,end=anchor<=15?15:last;return all.filter(([k])=>{const x=+k.slice(-2);return x>=start&&x<=end})}return all}
function dashValue(d,metric){const sv=num(d.warranty)+num(d.other)+num(d.mixed);if(metric==='services')return sv;if(metric==='conversion')return num(d.nfs)?num(d.warrantyQty)/num(d.nfs)*100:0;if(metric==='efficiency')return num(d.eligible)?sv/num(d.eligible)*100:0;if(metric==='ticket')return num(d.invoiceCount)?num(d.general)/num(d.invoiceCount):0;if(metric==='gain'){const mc=Object.prototype.hasOwnProperty.call(d,'commissionMercantile')?num(d.commissionMercantile):num(d.general)*num(d.commissionMercantileRate)/100;const sc=Object.prototype.hasOwnProperty.call(d,'commissionService')?num(d.commissionService):sv*.05;return mc+sc}return num(d.general)}
function dashFmt(v,m){return ['conversion','efficiency'].includes(m)?`${Number(v||0).toFixed(1).replace('.',',')}%`:brl.format(v||0)}
function dashAxisFmt(v,m){if(['conversion','efficiency'].includes(m))return `${Number(v||0).toFixed(v>=10?0:1).replace('.',',')}%`;const n=Number(v||0);if(n>=1e6)return `R$ ${(n/1e6).toFixed(1).replace('.',',')} mi`;if(n>=1000)return `R$ ${(n/1000).toFixed(n>=10000?0:1).replace('.',',')} mil`;return `R$ ${n.toFixed(0).replace('.',',')}`}
